namespace ChaChing.Domain.Billing.Quotes
{
    /// <summary>The public reference of a sent quote, e.g. DEV-2026-0042. Assigned by <see cref="Quote.MarkAsSent"/>, never generated by the domain (ADR 0013).</summary>
    public record QuoteNumber(int Year, int Sequence)
    {
        public int Year { get; } = ValidateYear(Year);

        public int Sequence { get; } = ValidateSequence(Sequence);

        public override string ToString() => $"DEV-{Year}-{Sequence:D4}";

        static int ValidateYear(int year)
        {
            if (year < 2000 || year > 9999)
                throw new ArgumentOutOfRangeException(nameof(year), "The year must have 4 digits, from 2000.");
            return year;
        }

        static int ValidateSequence(int sequence)
        {
            if (sequence < 1)
                throw new ArgumentOutOfRangeException(nameof(sequence), "The sequence starts at 1.");
            return sequence;
        }
    }
}
